import{_ as a,o as s,c as i,a5 as t}from"./chunks/framework.BwlBv862.js";const k=JSON.parse('{"title":"性能与有界工作","description":"","frontmatter":{"title":"性能与有界工作","docId":"developer.performance","translationKey":"developer.performance","locale":"zh","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"04bc0a89b86724872adae3ab8ddc8e29f5517dad14d51bc103d917582cf289ae","translationRevision":"c7d321ffaf8882e93e6c904aa72cf22ecb9e0c9f335022a03ad6ee11932658da","order":110},"headers":[],"relativePath":"zh/developer/performance.md","filePath":"zh/developer/performance.md","lastUpdated":1794611623000}'),r={name:"zh/developer/performance.md"};function n(o,e,l,h,d,p){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="performance-and-bounded-work" tabindex="-1">性能与有界工作 <a class="header-anchor" href="#performance-and-bounded-work" aria-label="Permalink to &quot;性能与有界工作 {#performance-and-bounded-work}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目标与前置条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目标与前置条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>在保留事件记账和正常关闭能力的前提下测量具体瓶颈。从固定构建、确定性输入和隔离配置开始。先阅读<a href="./events.html">事件</a>，避免把更快的事件流误认为更可靠的持久化。历史基准数字仅描述当时指定构建和机器的观察结果，不是当前产品保证。</p><h2 id="measure-the-right-boundary" tabindex="-1">测量正确边界 <a class="header-anchor" href="#measure-the-right-boundary" aria-label="Permalink to &quot;测量正确边界 {#measure-the-right-boundary}&quot;">​</a></h2><p>桌面发件箱区分允许丢失的展示与可靠响应。快照可合并；可靠通道溢出必须明确失败。直播入口、插件工作、处理器调用和自动化准入各有边界。增大一个队列可能把内存压力或延迟转移到下一阶段。</p><p>前端运行时在开发模式，或以 <code>VITE_TIKTOOLS_DIAGNOSTICS=1</code> 构建时，公开聚合诊断。快照包含已渲染行数、帧间隔百分位、控制客户端待处理调用、图片及所属定时器。特定 WebView 可能无法提供 JavaScript 堆数据。隐藏页面与宿主可见性决定展示兴趣，不影响业务记账。</p><h2 id="run-a-focused-comparison" tabindex="-1">进行针对性比较 <a class="header-anchor" href="#run-a-focused-comparison" aria-label="Permalink to &quot;进行针对性比较 {#run-a-focused-comparison}&quot;">​</a></h2><ol><li>记录构建修订、平台、事件组合、是否启用图片、可见标签页及持续时间。</li><li>使用相同夹具和采样周期建立基准。</li><li>改变一个边界，再比较吞吐量、p95/p99 延迟、队列丢弃、缺口、保留内存及关闭排空行为。</li><li>包含慢插件或慢消费者及饱和队列；空闲基准无法测试背压。</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> live-feed-state</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tiktools-core</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --features</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> persistence,native-tiktok</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> live_throughput</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span></span></code></pre></div><p>启用原生基准前检查功能要求；普通针对性单元检查无需真实 TikTok 连接。以 <code>crates/tiktools-core/tests/live_throughput.rs</code> 和桌面发件箱测试作为实现参考。</p><h2 id="expected-result-and-status" tabindex="-1">预期结果与状态 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;预期结果与状态 {#expected-result-and-status}&quot;">​</a></h2><p>有界投影与准入路径已实现，并提供计数器和缺口报告。<a href="https://github.com/nglmercer/TikTools-app/blob/remake/crates/tiktools-core/src/services/points/queue.rs" target="_blank" rel="noreferrer">当前有序写入器</a>在修改内存前拒绝饱和写入，且禁止同步写入回退。旧性能报告描述的是已被替代的排序缺陷。应依据当前实现/测试评估缓存边界和故障恢复，不能从 UI 内存有界推断整体完全正确。</p><h2 id="recover" tabindex="-1">恢复方法 <a class="header-anchor" href="#recover" aria-label="Permalink to &quot;恢复方法 {#recover}&quot;">​</a></h2><p>帧表现改善而记账健康恶化时，撤回边界改动，并检查写入器/准入结果。隐藏标签页的定时器增长时，按<a href="./lifecycle.html">生命周期清理</a>排查。报告中保留原始输入数、接受数及丢失分类。缺口恢复可修复显示状态，不能修复已被拒绝或结果不确定的效果。</p>`,14)])])}const u=a(r,[["render",n]]);export{k as __pageData,u as default};
